import { test, expect } from '@playwright/test';

test.describe('Async Login Spinner', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should display spinner during login request', async ({ page }) => {
    await page.getByLabel('Username').fill('testuser');
    await page.getByLabel('Password').fill('password123');
    await page.getByRole('button', { name: 'Login' }).click();

    const spinner = page.getByText('Loading...');
    await expect(spinner).toBeVisible();

    // Simulate waiting for the async request to complete
    await page.waitForTimeout(3000); // Adjust timeout as necessary

    await expect(spinner).not.toBeVisible();
  });

  test('should not display spinner if login fails', async ({ page }) => {
    await page.getByLabel('Username').fill('wronguser');
    await page.getByLabel('Password').fill('wrongpassword');
    await page.getByRole('button', { name: 'Login' }).click();

    const spinner = page.getByText('Loading...');
    await expect(spinner).toBeVisible();

    // Simulate waiting for the async request to complete
    await page.waitForTimeout(3000); // Adjust timeout as necessary

    await expect(spinner).not.toBeVisible();
    await expect(page.getByText('Invalid credentials')).toBeVisible();
  });
});
